 1	/**
 2	 * Tests for the createNamespacedProject fixture factory.
 3	 *
 4	 * Verifies that the factory:
 5	 *   AC1 — creates a properly namespaced project directory at
 6	 *          {ledgerRoot}/{repo}/{slug}/
 7	 *   AC2 — writes a valid project-ledger.json readable by LedgerStore
 8	 *   AC3 — LedgerStore.repoName resolves to the supplied `repo` argument
 9	 *   AC4 — cleanupNamespacedProject removes the temp directory
10	 *   AC5 — rootOverrides are applied to the written RootIndex
11	 */
12	
13	import { describe, it, expect, afterEach } from 'vitest';
14	import { access } from 'fs/promises';
15	import { join } from 'path';
16	import { constants } from 'fs';
17	import {
18	  createNamespacedProject,
19	  cleanupNamespacedProject,
20	  type NamespacedProjectHandle,
21	} from './create-namespaced-project.js';
22	import { LedgerStore } from '../../../src/storage/ledger-store.js';
23	
24	describe('createNamespacedProject fixture factory', () => {
25	  let handle: NamespacedProjectHandle | undefined;
26	
27	  afterEach(async () => {
28	    if (handle) {
29	      await cleanupNamespacedProject(handle);
30	      handle = undefined;
31	    }
32	  });
33	
34	  it('AC1: creates the {ledgerRoot}/{repo}/{slug}/ storage directory', async () => {
35	    handle = await createNamespacedProject('test-repo', '2026-01-15-my-feature');
36	
37	    // The storage directory must exist: {ledgerRoot}/{repo}/{slug}/
38	    const expectedDir = join(handle.ledgerRoot, 'test-repo', '2026-01-15-my-feature');
39	    await expect(access(expectedDir, constants.F_OK)).resolves.toBeUndefined();
40	  });
41	
42	  it('AC1: project-ledger.json is written at the correct path', async () => {
43	    handle = await createNamespacedProject('my-org', '2026-03-01-alpha');
44	
45	    const ledgerFile = join(
46	      handle.ledgerRoot,
47	      'my-org',
48	      '2026-03-01-alpha',
49	      'project-ledger.json'
50	    );
51	    await expect(access(ledgerFile, constants.F_OK)).resolves.toBeUndefined();
52	  });
53	
54	  it('AC2: LedgerStore can read back the written RootIndex', async () => {
55	    handle = await createNamespacedProject('acme-corp', '2026-06-01-test-slug');
56	
57	    const stored = new LedgerStore(handle.planPath, handle.ledgerRoot);
58	    const root = await stored.readRootIndex();
59	
60	    expect(root.status).toBe('IN_PROGRESS');
61	    expect(root.plan_file).toBe('plan.md');
62	    expect(root.work_packages).toEqual([]);
63	  });
64	
65	  it('AC3: store.repoName resolves to the supplied repo argument', async () => {
66	    handle = await createNamespacedProject('special-repo', '2026-02-28-naming-test');
67	
68	    expect(handle.store.repoName).toBe('special-repo');
69	    expect(handle.store.slug).toBe('2026-02-28-naming-test');
70	  });
71	
72	  it('AC4: cleanupNamespacedProject removes the ledgerRoot directory', async () => {
73	    const h = await createNamespacedProject('cleanup-repo', '2026-01-01-cleanup');
74	    const { ledgerRoot } = h;
75	
76	    await cleanupNamespacedProject(h);
77	    handle = undefined; // prevent double-cleanup in afterEach
78	
79	    await expect(access(ledgerRoot, constants.F_OK)).rejects.toThrow();
80	  });
81	
82	  it('AC5: rootOverrides are applied to the written RootIndex', async () => {
83	    handle = await createNamespacedProject(
84	      'override-repo',
85	      '2026-04-01-with-overrides',
86	      { status: 'COMPLETE', total_work_packages: 5, pending_work_packages: 0 }
87	    );
88	
89	    const root = await handle.store.readRootIndex();
90	
91	    expect(root.status).toBe('COMPLETE');
92	    expect(root.total_work_packages).toBe(5);
93	    expect(root.pending_work_packages).toBe(0);
94	  });
95	});

 1	/**
 2	 * Shared test helper: createTempStore
 3	 *
 4	 * ## Purpose
 5	 * Provides a reusable factory that always pairs a `LedgerStore` with a
 6	 * `mkdtemp`-based ledger root, ensuring tests never accidentally write to the
 7	 * real `storage/ledger/` directory.
 8	 *
 9	 * ## Usage
10	 *
11	 * ```ts
12	 * import { createTempStore, cleanupTempStore } from '../helpers/create-temp-store.js';
13	 *
14	 * let handle: Awaited<ReturnType<typeof createTempStore>>;
15	 *
16	 * beforeEach(async () => {
17	 *   handle = await createTempStore('/absolute/path/to/plan-folder');
18	 * });
19	 *
20	 * afterEach(async () => {
21	 *   await cleanupTempStore(handle);
22	 * });
23	 *
24	 * it('writes something', async () => {
25	 *   await handle.store.writeRootIndex(root);
26	 * });
27	 * ```
28	 *
29	 * ## Convention contract
30	 * Every test file that constructs a `LedgerStore` MUST supply an isolated
31	 * ledger root obtained from `mkdtemp`. Passing a production path (e.g. the
32	 * real `storage/ledger/` directory) from within tests is forbidden because it
33	 * contaminates version-controlled storage and causes stale artifact
34	 * accumulation across CI runs.
35	 *
36	 * `createTempStore` makes this the path of least resistance: callers get both
37	 * the store and the temp directory handle from a single awaitable call, and
38	 * `cleanupTempStore` disposes both atomically.
39	 */
40	
41	import { mkdtemp, rm } from 'fs/promises';
42	import { join } from 'path';
43	import { tmpdir } from 'os';
44	import { LedgerStore } from '../../src/storage/ledger-store.js';
45	
46	export interface TempStoreHandle {
47	  /** Isolated LedgerStore instance backed by a temporary directory. */
48	  store: LedgerStore;
49	  /** Absolute path to the plan folder passed to LedgerStore. */
50	  planPath: string;
51	  /** Absolute path to the temporary ledger root (the mkdtemp directory). */
52	  ledgerRoot: string;
53	}
54	
55	/**
56	 * Creates a `LedgerStore` backed by a fresh `mkdtemp` directory.
57	 *
58	 * @param planPath - Absolute path to the plan folder (used as the project path
59	 *   argument to LedgerStore). Under test this can be a fixed synthetic path
60	 *   such as `join(tmpdir(), '2026-01-01-test-project')` — it does not need to
61	 *   exist on disk.
62	 * @param prefix - Optional prefix for the temporary directory name.
63	 *   Defaults to `'ledger-test-'`.
64	 * @returns A {@link TempStoreHandle} containing the store, planPath, and
65	 *   ledgerRoot for use in `afterEach` cleanup.
66	 */
67	export async function createTempStore(
68	  planPath: string,
69	  prefix = 'ledger-test-'
70	): Promise<TempStoreHandle> {
71	  const ledgerRoot = await mkdtemp(join(tmpdir(), prefix));
72	  const store = new LedgerStore(planPath, ledgerRoot);
73	  return { store, planPath, ledgerRoot };
74	}
75	
76	/**
77	 * Removes the temporary ledger root directory created by {@link createTempStore}.
78	 * Safe to call even if the directory was never written to.
79	 */
80	export async function cleanupTempStore(handle: TempStoreHandle): Promise<void> {
81	  await rm(handle.ledgerRoot, { recursive: true, force: true });
82	}

