34	/**
35	 * Thrown by `LedgerStore.renameSlug()` when the target slug directory already
36	 * exists on disk (i.e. the slug is taken by another project).
37	 */
38	export class SlugConflictError extends Error {
39	  constructor(slug: string) {
40	    super(`Slug already in use: "${slug}".`);
41	    this.name = 'SlugConflictError';
42	  }
43	}
44	
45	/**
46	 * Central storage abstraction for ledger file I/O.
47	 *
48	 * All reads validate with Zod schemas.
49	 * All writes use atomic operations and file locking.
50	 *
51	 * Files are stored in the centralized ledger root at `{ledgerRoot}/{repoName}/{slug}/`
52	 * rather than inside the plan folder.
53	 */
54	export class LedgerStore {
55	  public readonly planPath: string;
56	  public readonly slug: string;
57	  public readonly ledgerRoot: string;
58	  public readonly repoName: string;
59	  public readonly storageDir: string;
